$base='https://pakthai-ai-sourcing.pakthaitech.workers.dev'
$body=@{settings=@{country_south_korea_enabled=$true;country_thailand_enabled=$true;country_pakistan_enabled=$true;pakistan_source_enabled=$true}}|ConvertTo-Json -Depth 5 -Compress
try{$r=Invoke-RestMethod -Uri ($base+'/api/settings') -Method Post -ContentType 'application/json' -Body $body -TimeoutSec 20;Write-Output ('POST settings ok='+$r.ok);foreach($k in @('country_thailand_enabled','country_south_korea_enabled','country_pakistan_enabled','pakistan_source_enabled')){Write-Output ($k+'='+$r.settings.$k)}}catch{Write-Output ('POST ERROR '+$_.Exception.Message);if($_.ErrorDetails.Message){Write-Output $_.ErrorDetails.Message}}
try{$c=Invoke-RestMethod -Uri ($base+'/api/controls') -TimeoutSec 20;Write-Output ('VERIFY Thailand='+$c.controls.countries.Thailand+' SouthKorea='+$c.controls.countries.'South Korea'+' Pakistan='+$c.controls.countries.Pakistan+' PakistanSource='+$c.controls.countries.PakistanSource)}catch{Write-Output ('VERIFY ERROR '+$_.Exception.Message)}
try{$r=Invoke-WebRequest -Uri ($base+'/api/buyer-match/run') -Method Post -ContentType 'application/json' -Body '{}' -UseBasicParsing -TimeoutSec 25;$j=$r.Content|ConvertFrom-Json;Write-Output ('BUYER_MATCH HTTP '+[int]$r.StatusCode+' '+$r.Content.Substring(0,[Math]::Min(1200,$r.Content.Length)))}catch{Write-Output ('BUYER_MATCH ERROR '+$_.Exception.Message);if($_.ErrorDetails.Message){Write-Output $_.ErrorDetails.Message}}